// Acepta JSON {image_base64, mode, prompt} o multipart con un archivo de imagen.
const item = $input.first();
const body = item.json.body || {};
let image = body.image_base64 || body.image || null;
if (image && image.includes(',')) image = image.split(',').pop(); // data URL -> base64
if (!image && item.binary) {
  const key = Object.keys(item.binary)[0];
  if (key) image = (await this.helpers.getBinaryDataBuffer(0, key)).toString('base64');
}
if (!image) throw new Error('Falta la imagen: envia image_base64 (JSON) o un archivo multipart.');

const prompts = {
  texto: 'Transcribe fielmente todo el texto visible en la imagen respetando el orden de lectura. Devuelve solo el texto, sin comentarios.',
  documento: 'Extrae la informacion de este documento. Devuelve SOLO un JSON valido con las claves: tipo_documento (string), idioma (string), texto_completo (string), campos (objeto clave-valor con los datos detectados), tablas (arreglo de filas), fechas (arreglo de strings), montos (arreglo de strings). Usa null cuando algo no exista. No inventes datos.',
  salud: 'Esta imagen es un documento clinico o administrativo de salud. Transcribe sin interpretar ni diagnosticar. Devuelve SOLO un JSON valido con las claves: tipo_documento, texto_completo, campos (paciente, rut, fecha, profesional, institucion, segun existan), medicamentos (arreglo de {nombre, dosis, frecuencia, duracion}), indicaciones (arreglo de strings), ilegible (arreglo con fragmentos que no pudiste leer). Usa null cuando algo no exista. No inventes datos.',
};
const mode = prompts[body.mode] ? body.mode : 'documento';
return [{ json: { image, mode, prompt: body.prompt || prompts[mode] } }];

const cfg = $('Config Modelo').first().json;
const content = String(($json.message && $json.message.content) || '').replace(/<think>[\s\S]*?<\/think>/g, '').trim();
let fields = null;
if (cfg.mode !== 'texto') {
  const cleaned = content.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();
  try { fields = JSON.parse(cleaned); } catch (e) { fields = null; }
}
const text = fields && typeof fields.texto_completo === 'string' ? fields.texto_completo : content;
return [{ json: { ok: true, model: cfg.model, mode: cfg.mode, text, fields, raw: fields ? undefined : content } }];
